def count_returnable_rooms(t, test_cases):
    results = []

    for i in range(t):
        n = int(test_cases[i][0])
        s = test_cases[i][1]

        def is_returnable(pos):
            visited = set()
            stack = [(pos, 0)]

            while stack:
                current, direction = stack.pop()

                if current in visited:
                    continue

                visited.add(current)

                if direction == 0:  # Clockwise
                    if s[current] == '>':
                        stack.append((current + 1) % n, 1)
                    elif s[current] == '<':
                        stack.append((current - 1) % n, 2)
                    elif s[current] == '-':
                        stack.append((current + 1) % n, 1)
                        stack.append((current - 1) % n, 2)
                elif direction == 1:  # Anticlockwise
                    if s[current] == '<':
                        stack.append((current - 1) % n, 2)
                    elif s[current] == '>':
                        stack.append((current + 1) % n, 1)
                    elif s[current] == '-':
                        stack.append((current + 1) % n, 1)
                        stack.append((current - 1) % n, 2)
                else:  # Off
                    stack.append((current + 1) % n, 1)
                    stack.append((current - 1) % n, 2)

                if len(visited) == n:
                    return True

            return False

        count = 0
        for j in range(n):
            if is_returnable(j):
                count += 1

        results.append(count)

    return results

