        visited = [False] * n
        stack = []

        def dfs(start):
            stack.append(start)
            visited[start] = True

            while stack:
                current = stack[-1]

                found_next = False
                for i in range(n):
                    if (s[i] == '>' and (current == i or current + 1 == i)) or \
                       (s[i] == '<' and (current == i or (current + 1) % n == i)):
                        next_room = (i + 1) % n
                        if not visited[next_room]:
                            stack.append(next_room)
                            visited[next_room] = True
                            found_next = True
                            break

                if not found_next:
                    stack.pop()

            return any(visited[i] for i in range(n))

        for i in range(n):
            if not visited[i] and not dfs(i):
                break

        result = n - len([i for i in range(n) if visited[i]])
        results.append(result)

    return results

