                state[(i + 1) % n] = 1
            elif s[i] == '<':
                state[i] = -1

        # Count the number of returnable rooms
        count = 0
        for i in range(n):
            if state[i] == 0:
                j = (i + 1) % n
                while j != i and state[j] != -1:
                    if state[j] == 1:
