            results.append(n)
        else:
            clockwise = [i for i, char in enumerate(s) if char == '>']
            anticlockwise = [i for i, char in enumerate(s) if char == '<']
            off = [i for i, char in enumerate(s) if char == '-']

            reachable_from_off = set()
            stack = list(off)
            while stack:
                current = stack.pop()
                for neighbor in [(current - 1 + n) % n, (current + 1) % n]:
                    if s[neighbor] != '-' and neighbor not in reachable_from_off:
                        reachable_from_off.add(neighbor)
                        stack.append(neighbor)

            returnable_count = 0
            for i in range(n):
                if i not in reachable_from_off:
                    if all((i + j) % n in reachable_from_off or (i - j) % n in reachable_from_off for j in range(1, n)):
                        returnable_count += 1

            results.append(returnable_count)

    return results

