def count_returnable_rooms(t, test_cases):
    results = []

    for n, s in test_cases:
        count = 0
        visited = [False] * n

        def dfs(current):
            nonlocal count
            if visited[current]:
                return True
            visited[current] = True

            for i in range(n):
                if s[i % n] == '>' and i % n != current:
                    if dfs((current + 1) % n):
                        count += 1
                        break
                elif s[i % n] == '<' and i % n != current:
                    if dfs((current - 1 + n) % n):
                        count += 1
                        break
                elif s[i % n] == '-' and i % n != current:
                    if dfs((i + 1) % n) or dfs((i - 1 + n) % n):
                        count += 1
                        break

            return False

        for i in range(n):
            if not visited[i]:
                dfs(i)

        results.append(count)

    return results

